Local Ltac r3v X d0 b0 b1 b2 b3 Eb0 Et Eb1 Eb2 WIN PASS V R10 R12 R23 R24 :=
  lazymatch goal with |- goal_from _ ?fx ?R _ =>
    runpk X fx R (fun j => match j with 2%nat => S | 33%nat => d0 | 35%nat => e - d0 | 36%nat => sx8u b0 | 37%nat => b0 | 39%nat => b3 | _ => 0 end)
      ltac:(fun EX =>
    destruct EX as [EX|EX]; msks EX;
    [ cexit_err d0 b0 3 Eb0 Et WIN V
    | gpre; lazymatch goal with CB : 128 <= b3 < 192 |- _ =>
        apply (r2_case _ _ d0 3 b0 b1 b2 [b3] ltac:(lia) ltac:(lia) ltac:(lia) Eb0 Et Eb1 Eb2 WIN (PASS CB));
        [vk V| kept 10%nat R10| assumption| replace (d0 + 3 + 1) with (d0 + 4) by (clear; lia); kept 12%nat R12| kept 23%nat R23| kept 24%nat R24] end ])
  end.
Lemma r3_case fx R d0 b0 b1 b2 b3 :
  p <= c <= d0 -> d0 + 4 <= e -> b0 = bat l (d0 - p) -> 3 = utf8_trail b0 -> b1 = bat l (d0 - p + 1) -> b2 = bat l (d0 - p + 2) -> b3 = bat l (d0 - p + 3) ->
  firstn (Z.to_nat (3 + 1)) (skipn (Z.to_nat (d0 - p)) l) = [b0; b1; b2; b3] ->
  (128 <= b3 < 192 -> 128 <= b2 < 192 -> 128 <= b1 < 192 -> second_ok b0 b1 -> lead_ok b0 -> utf8_legal [b0; b1; b2; b3] = true) ->
  vconst R -> getr R (reg 10) = Z_to_bv 64 d0 -> getr R (reg 13) = Z_to_bv 64 (d0 + 3) -> getr R (reg 12) = Z_to_bv 64 (d0 + 4) ->
  getr R (reg 26) = Z_to_bv 64 (d0 + 4) -> getr R (reg 23) = Z_to_bv 64 (sx8u b0) -> getr R (reg 24) = Z_to_bv 64 b0 -> goal_from d0 fx R 0xcd70c.
